import{_ as r,o as t,c as l,a5 as i}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"912-批量提取每个word文档内容到创建的同名文件夹生成txt和图片","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["WORD批处理"],"标签":["Python文档处理","Word文档工具","Word文档批量处理","Word转TXT","批量文档处理工具","提取Word图片","提取Word文本","文档内容提取"]},"headers":[],"relativePath":"md/WORD批处理/912-批量提取每个word文档内容到创建的同名文件夹生成txt和图片.md","filePath":"md/WORD批处理/912-批量提取每个word文档内容到创建的同名文件夹生成txt和图片.md"}'),a={name:"md/WORD批处理/912-批量提取每个word文档内容到创建的同名文件夹生成txt和图片.md"};function e(n,o,d,s,p,g){return t(),l("div",null,[...o[0]||(o[0]=[i('<p>这是一个简单易用的Word文档批量处理工具，专门帮助您快速从Word文档中提取文本内容和图片。无论您有多少个Word文档需要处理，这个工具都能帮您自动完成，无需手动一个个打开文档复制粘贴。</p><p>工具的主要作用是：当您有一堆Word文档，想要把每个文档里的文字提取成文本文件，同时把文档里的图片也单独保存出来时，这个工具可以帮您一键完成所有工作。每个Word文档会自动创建一个对应的文件夹，里面包含提取出的文本文件和所有图片，让您的文件管理更加清晰有序。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260221194310177167419024182.jpg" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><ul><li><strong>批量处理</strong>：可以一次性处理多个Word文档，支持同时处理整个文件夹中的所有Word文件</li><li><strong>文本提取</strong>：自动提取Word文档中的所有文字内容，保存为UTF-8编码的文本文件，确保中文显示正常</li><li><strong>图片提取</strong>：智能识别并提取文档中嵌入的所有图片，支持PNG、JPG、GIF、BMP、WEBP多种格式</li><li><strong>自动分类</strong>：为每个Word文档自动创建独立的文件夹，文档名作为文件夹名，方便管理和查找</li><li><strong>子文件夹支持</strong>：可选择是否处理子文件夹中的Word文档，并保持原有的文件夹结构</li></ul><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><h4 id="步骤一-选择源路径" tabindex="-1">步骤一：选择源路径 <a class="header-anchor" href="#步骤一-选择源路径" aria-label="Permalink to &quot;步骤一：选择源路径&quot;">​</a></h4><p>源路径可以是包含Word文档的文件夹，也可以是单个Word文件。您有两种方式设置：</p><p><strong>方式1：使用浏览按钮</strong></p><ol><li>点击”word文档文件夹路径”输入框旁边的”浏览”按钮</li><li>在弹出的文件夹选择对话框中，找到并选择包含Word文档的文件夹（或选择单个Word文件）</li><li>点击”确定”，路径会自动填入输入框</li></ol><p><strong>方式2：拖拽文件</strong></p><ol><li>打开文件资源管理器，找到您的Word文档或包含Word文档的文件夹</li><li>直接用鼠标拖拽文件或文件夹到”word文档文件夹路径”输入框中</li><li>松开鼠标，路径会自动填入</li></ol><h4 id="步骤二-选择目标路径" tabindex="-1">步骤二：选择目标路径 <a class="header-anchor" href="#步骤二-选择目标路径" aria-label="Permalink to &quot;步骤二：选择目标路径&quot;">​</a></h4><p>目标路径是保存提取结果的位置。同样有两种方式：</p><p><strong>方式1：使用浏览按钮</strong></p><ol><li>点击”需要保存到的文件夹路径”输入框旁边的”浏览”按钮</li><li>选择或创建一个用于保存结果的文件夹</li><li>点击”确定”</li></ol><p><strong>方式2：拖拽文件夹</strong></p><ol><li>在文件资源管理器中找到目标文件夹</li><li>拖拽到”需要保存到的文件夹路径”输入框中</li></ol><h4 id="步骤三-设置处理选项" tabindex="-1">步骤三：设置处理选项 <a class="header-anchor" href="#步骤三-设置处理选项" aria-label="Permalink to &quot;步骤三：设置处理选项&quot;">​</a></h4><p>根据您的需求，决定是否勾选”穿透子文件夹”选项：</p><ul><li><strong>不勾选</strong>：只处理源文件夹中的直接文件，不处理子文件夹中的Word文档</li><li><strong>勾选</strong>：会处理所有子文件夹中的Word文档，并在目标文件夹中保持相同的文件夹结构</li></ul><h4 id="步骤四-开始处理" tabindex="-1">步骤四：开始处理 <a class="header-anchor" href="#步骤四-开始处理" aria-label="Permalink to &quot;步骤四：开始处理&quot;">​</a></h4><ol><li>确认源路径和目标路径都已正确设置</li><li>点击”开始处理”按钮</li><li>工具会开始处理，您可以在日志区域看到实时处理信息</li><li>进度条会显示处理进度百分比</li><li>处理完成后，会显示成功和失败的文件数量</li></ol><h4 id="步骤五-查看结果" tabindex="-1">步骤五：查看结果 <a class="header-anchor" href="#步骤五-查看结果" aria-label="Permalink to &quot;步骤五：查看结果&quot;">​</a></h4><p>处理完成后，您可以：</p><ol><li>打开目标文件夹，您会看到为每个Word文档创建的独立文件夹</li><li>进入任意一个文档文件夹，里面包含： <ul><li>一个<code>.txt</code>文本文件，包含文档的所有文字内容</li><li>多个图片文件（如果文档中有图片），命名格式为”文档名@序号.jpg”</li></ul></li></ol><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><h4 id="场景一-整理工作文档" tabindex="-1">场景一：整理工作文档 <a class="header-anchor" href="#场景一-整理工作文档" aria-label="Permalink to &quot;场景一：整理工作文档&quot;">​</a></h4><p><strong>背景</strong>：小王是一名办公室文员，手头有50个Word格式的工作报告，需要把每个报告的文字内容提取出来，方便后续进行文本分析和搜索。</p><p><strong>操作步骤</strong>：</p><ol><li>小王将所有50个Word文档放在一个文件夹中，例如<code>D:\\工作报告\\2024年报告</code></li><li>打开工具，在源路径中选择<code>D:\\工作报告\\2024年报告</code></li><li>在目标路径中选择<code>D:\\工作报告\\提取结果</code></li><li>由于所有文档都在同一层，不需要处理子文件夹，所以不勾选”穿透子文件夹”</li><li>点击”开始处理”</li><li>等待处理完成，工具显示”处理完成！成功: 50, 失败: 0”</li><li>小王打开<code>D:\\工作报告\\提取结果</code>文件夹，看到50个文件夹，每个对应一个Word文档</li><li>进入任意文件夹，都能找到对应的<code>.txt</code>文本文件，可以直接用记事本打开查看</li></ol><p><strong>结果</strong>：小王成功提取了所有报告的文字内容，现在可以方便地进行全文搜索和文本分析了。</p><h4 id="场景二-提取文档中的图片素材" tabindex="-1">场景二：提取文档中的图片素材 <a class="header-anchor" href="#场景二-提取文档中的图片素材" aria-label="Permalink to &quot;场景二：提取文档中的图片素材&quot;">​</a></h4><p><strong>背景</strong>：设计师小李需要从客户提供的产品说明文档中提取所有产品图片，用于制作宣传材料。文档结构比较复杂，包含多个子文件夹。</p><p><strong>操作步骤</strong>：</p><ol><li>小李的文档存放在<code>E:\\客户资料\\产品说明</code>文件夹中，里面还有多个子文件夹，如”产品A”、”产品B”等</li><li>打开工具，在源路径中选择<code>E:\\客户资料\\产品说明</code></li><li>在目标路径中选择<code>E:\\客户资料\\提取的图片</code></li><li>由于需要处理所有子文件夹，勾选”穿透子文件夹”选项</li><li>点击”开始处理”</li><li>工具开始处理，日志显示找到了120个Word文档</li><li>处理过程中，日志显示每个文档提取的图片数量，例如”提取了 5 张图片”</li><li>处理完成后，小李打开目标文件夹</li><li>由于勾选了穿透子文件夹，目标文件夹中保持了原有的文件夹结构</li><li>进入任意文档文件夹，都能看到提取出的图片文件，命名清晰，如”产品说明<a href="https://github.com/1" target="_blank" rel="noreferrer">@1</a>.jpg”、”产品说明<a href="https://github.com/2" target="_blank" rel="noreferrer">@2</a>.jpg”等</li></ol><p><strong>结果</strong>：小李成功提取了所有文档中的图片，现在可以直接使用这些图片素材进行设计工作了。</p><h4 id="场景三-批量转换文档格式" tabindex="-1">场景三：批量转换文档格式 <a class="header-anchor" href="#场景三-批量转换文档格式" aria-label="Permalink to &quot;场景三：批量转换文档格式&quot;">​</a></h4><p><strong>背景</strong>：教师张老师需要将学生提交的Word格式作业转换为纯文本格式，方便进行查重和批改。有些学生提交的是单个文件，有些提交的是包含多个文档的文件夹。</p><p><strong>操作步骤</strong>：</p><ol><li>张老师将所有学生作业放在<code>C:\\学生作业\\2024春季学期</code>文件夹中</li><li>打开工具，在源路径中选择<code>C:\\学生作业\\2024春季学期</code></li><li>在目标路径中选择<code>C:\\学生作业\\文本格式作业</code></li><li>勾选”穿透子文件夹”，因为有些学生提交的是文件夹</li><li>点击”开始处理”</li><li>工具处理了200个Word文档，有些文档有图片也被提取出来了</li><li>处理完成后，张老师打开目标文件夹</li><li>每个学生的作业都有对应的文件夹，里面包含文本文件</li><li>张老师可以直接打开<code>.txt</code>文件查看作业内容，或者使用文本处理工具进行批量操作</li></ol><p><strong>结果</strong>：张老师成功将所有Word格式的作业转换为文本格式，现在可以方便地进行查重和批改了。</p><h3 id="数据存储位置" tabindex="-1">数据存储位置 <a class="header-anchor" href="#数据存储位置" aria-label="Permalink to &quot;数据存储位置&quot;">​</a></h3><h4 id="提取结果存储位置" tabindex="-1">提取结果存储位置 <a class="header-anchor" href="#提取结果存储位置" aria-label="Permalink to &quot;提取结果存储位置&quot;">​</a></h4><p>所有提取的结果都保存在您指定的目标文件夹中。每个Word文档会创建一个以文档名（不含扩展名）命名的文件夹，例如：</p><ul><li>如果源文档是<code>报告.docx</code>，会创建<code>报告</code>文件夹</li><li>如果源文档是<code>产品说明.doc</code>，会创建<code>产品说明</code>文件夹</li></ul><p>在每个文档文件夹中：</p><ul><li><strong>文本文件</strong>：保存为<code>文档名.txt</code>，使用UTF-8编码，可以用任何文本编辑器打开</li><li><strong>图片文件</strong>：保存为<code>文档名@序号.jpg</code>格式，例如<code>报告[@1](https://github.com/1).jpg</code>、<code>报告[@2](https://github.com/2).jpg</code>等</li></ul><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ol><li><strong>备份重要数据</strong>：在处理重要文档之前，强烈建议先备份原始Word文档。虽然工具不会修改原始文档，但为了安全起见，建议保留备份。</li><li><strong>磁盘空间</strong>：提取图片会占用额外的磁盘空间，请确保目标文件夹所在磁盘有足够的可用空间。特别是处理大量包含图片的文档时，可能需要几GB甚至更多的空间。</li><li><strong>文件命名</strong>：如果目标文件夹中已存在同名的文件夹，工具会自动使用现有文件夹，可能会覆盖其中的文件。建议每次处理使用新的目标文件夹，或者先清空目标文件夹。</li><li><strong>处理时间</strong>：处理大量文档或包含大量图片的文档时，可能需要较长时间。请耐心等待，不要强制关闭程序。可以通过日志区域查看处理进度。</li><li><strong>文件格式支持</strong>：工具支持<code>.docx</code>和<code>.doc</code>格式的Word文档。其他格式（如<code>.txt</code>、<code>.pdf</code>等）不会被处理。</li><li><strong>隐藏文件</strong>：工具会自动跳过隐藏文件和临时文件（以<code>~$</code>开头的文件），这些通常是Word的临时文件，不需要处理。</li><li><strong>图片格式</strong>：提取的图片会统一保存为<code>.jpg</code>格式，即使原图是PNG或其他格式。这样可以确保兼容性和文件大小。</li><li><strong>编码问题</strong>：文本文件使用UTF-8编码保存，如果打开后中文显示乱码，请确保您的文本编辑器支持UTF-8编码。</li><li><strong>处理中断</strong>：如果在处理过程中点击”停止处理”或关闭程序，已处理完成的文件不会受影响，但未处理的文件需要重新运行工具处理。</li><li><strong>权限问题</strong>：如果遇到”拒绝访问”的错误，可能是目标文件夹没有写入权限。请确保目标文件夹不在系统保护目录中，或者以管理员身份运行工具。</li></ol><h3 id="常见问题使用解答" tabindex="-1">常见问题使用解答 <a class="header-anchor" href="#常见问题使用解答" aria-label="Permalink to &quot;常见问题使用解答&quot;">​</a></h3><p><strong>Q: 处理完成后，为什么有些文档的文件夹是空的？</strong></p><p>A: 可能的原因有：1）该Word文档本身就是空的，没有任何内容；2）文档中的内容都是图片或表格，没有可提取的文本；3）文档格式特殊，工具无法识别。请检查原始Word文档的内容。</p><p><strong>Q: 提取的图片为什么都是.jpg格式？</strong></p><p>A: 为了确保兼容性和统一管理，工具会将所有图片统一转换为.jpg格式保存。即使原图是PNG或其他格式，也会转换为.jpg。这样可以减少文件大小，提高兼容性。</p><p><strong>Q: 可以同时处理多少个文档？</strong></p><p>A: 理论上没有数量限制，但处理大量文档（如数千个）时，可能需要较长时间。建议分批处理，或者确保有足够的处理时间。工具会显示处理进度，您可以随时了解处理状态。</p><p><strong>Q: 处理过程中可以暂停吗？</strong></p><p>A: 可以。点击”停止处理”按钮可以随时停止处理。已处理完成的文件不会受影响，但未处理的文件需要重新运行工具处理。</p><p><strong>Q: 为什么有些图片提取不出来？</strong></p><p>A: 可能的原因有：1）图片是作为背景或水印嵌入的，不是标准的图片对象；2）图片格式特殊，工具无法识别；3）Word文档已损坏。请检查原始Word文档，确认图片是否正常显示。</p><p><strong>Q: 提取的文本文件打开后中文显示乱码，怎么办？</strong></p><p>A: 文本文件使用UTF-8编码保存。如果打开后乱码，请确保您的文本编辑器支持UTF-8编码。Windows自带的记事本从Windows 10开始支持UTF-8，如果使用旧版本，建议使用其他文本编辑器，如Notepad++、VS Code等。</p><p><strong>Q: 可以处理加密的Word文档吗？</strong></p><p>A: 不可以。</p><p><strong>Q: 处理速度很慢，是什么原因？</strong></p><p>A: 处理速度受多个因素影响：1）文档数量多；2）文档中包含大量图片；3）文档文件较大；4）计算机性能较低。这是正常现象，请耐心等待。可以通过日志查看处理进度。</p><p><strong>Q: 目标文件夹可以放在U盘或网络驱动器上吗？</strong></p><p>A: 可以，但处理速度可能会较慢，特别是网络驱动器。建议将目标文件夹设置在本地硬盘上，处理完成后再复制到U盘或网络驱动器。</p><p><strong>Q: 工具会修改原始Word文档吗？</strong></p><p>A: 不会。工具只读取Word文档的内容，不会对原始文档进行任何修改。原始文档保持完全不变。</p><p><strong>Q: 支持处理.docx和.doc格式，有什么区别吗？</strong></p><p>A: 工具对两种格式的处理方式相同，都会提取文本和图片。但.doc是旧格式，如果遇到兼容性问题，建议先将.doc转换为.docx格式再处理。</p><p><strong>Q: 如果处理过程中程序崩溃了，怎么办？</strong></p><p>A: 已处理完成的文件不会受影响，可以正常使用。未处理的文件需要重新运行工具处理。建议在处理大量文档前先测试处理少量文档，确保工具正常运行。</p><p><strong>Q: 可以只提取文本，不提取图片吗？</strong></p><p>A: 当前版本会同时提取文本和图片。如果文档中没有图片，就不会创建图片文件。如果需要只提取文本的功能，可以在处理完成后手动删除图片文件，或者联系开发者添加此功能。</p><p><strong>Q: 提取的图片质量会下降吗？</strong></p><p>A: 工具会尽量保持图片的原始质量。图片保存时使用95%的JPEG质量，对于大多数用途来说质量损失很小，肉眼几乎无法察觉。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后直接使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260221194041177167404163581.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2625.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2625.html</a></p>',89)])])}const u=r(a,[["render",e]]);export{h as __pageData,u as default};
